// Package diff computes and renders unified diffs between two pieces of text.
//
// It is intended to be embedded in testing tools that need to show what
// changed between an expected value and an actual value.
package diff

import (
	"github.com/pmezard/go-difflib/difflib"
)

// DefaultContext is the number of unchanged lines rendered around each change
// when Options.Context is not set.
const DefaultContext = 3

// Options controls how a unified diff is rendered.
type Options struct {
	// FromFile and ToFile are the labels printed in the ---/+++ headers.
	FromFile string
	ToFile   string

	// FromDate and ToDate are optional timestamps printed after the file
	// labels in the ---/+++ headers.
	FromDate string
	ToDate   string

	// Context is the number of unchanged lines rendered around each change.
	// Values less than or equal to zero use DefaultContext.
	Context int
}

// Unified renders a unified diff between oldText and newText using the default
// number of context lines. The returned string is empty when the inputs are
// identical.
func Unified(oldText, newText string) (string, error) {
	return UnifiedWithOptions(oldText, newText, Options{})
}

// UnifiedWithOptions renders a unified diff between oldText and newText using
// the supplied Options.
func UnifiedWithOptions(oldText, newText string, opts Options) (string, error) {
	context := opts.Context
	if context <= 0 {
		context = DefaultContext
	}

	ud := difflib.UnifiedDiff{
		A:        difflib.SplitLines(oldText),
		B:        difflib.SplitLines(newText),
		FromFile: opts.FromFile,
		ToFile:   opts.ToFile,
		FromDate: opts.FromDate,
		ToDate:   opts.ToDate,
		Context:  context,
		Eol:      "\n",
	}
	return difflib.GetUnifiedDiffString(ud)
}

// Equal reports whether oldText and newText are identical.
func Equal(oldText, newText string) bool {
	return oldText == newText
}

package diff

import (
	"strings"
	"testing"
)

func TestUnifiedIdentical(t *testing.T) {
	got, err := Unified("hello\nworld\n", "hello\nworld\n")
	if err != nil {
		t.Fatalf("Unified returned error: %v", err)
	}
	if got != "" {
		t.Fatalf("expected empty diff for identical input, got:\n%s", got)
	}
}

func TestUnifiedChange(t *testing.T) {
	oldText := "alpha\nbravo\ncharlie\n"
	newText := "alpha\nBRAVO\ncharlie\n"

	got, err := UnifiedWithOptions(oldText, newText, Options{
		FromFile: "old.txt",
		ToFile:   "new.txt",
	})
	if err != nil {
		t.Fatalf("UnifiedWithOptions returned error: %v", err)
	}

	for _, want := range []string{
		"--- old.txt",
		"+++ new.txt",
		"-bravo",
		"+BRAVO",
		" alpha",
		" charlie",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("diff missing %q; got:\n%s", want, got)
		}
	}
}

func TestUnifiedContext(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 20; i++ {
		b.WriteString("line\n")
	}
	oldText := b.String()
	newText := strings.Replace(oldText, "line\n", "LINE\n", 1)

	got, err := UnifiedWithOptions(oldText, newText, Options{Context: 1})
	if err != nil {
		t.Fatalf("UnifiedWithOptions returned error: %v", err)
	}

	if strings.Count(got, "\n line") != 1 {
		t.Errorf("expected a single context line with Context=1, got:\n%s", got)
	}
	if !strings.Contains(got, "-line") || !strings.Contains(got, "+LINE") {
		t.Errorf("diff missing change lines, got:\n%s", got)
	}
}

func TestEqual(t *testing.T) {
	if !Equal("same", "same") {
		t.Error("Equal returned false for identical input")
	}
	if Equal("a", "b") {
		t.Error("Equal returned true for different input")
	}
}

// Command difftool prints a unified diff between two pieces of text.
//
// Usage:
//
//	difftool [flags] OLD NEW
//
// OLD and NEW are file paths, or "-" to read from standard input.
// The exit status is 0 when the inputs are equal, 1 when they differ, and
// 2 when an error occurs.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"difftool/diff"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("difftool", flag.ContinueOnError)
	fs.SetOutput(stderr)

	context := fs.Int("context", diff.DefaultContext, "number of unchanged lines shown around each change")
	fromLabel := fs.String("from", "", "label for the old text in the --- header (defaults to the input path)")
	toLabel := fs.String("to", "", "label for the new text in the +++ header (defaults to the input path)")

	if err := fs.Parse(args); err != nil {
		return 2
	}

	paths := fs.Args()
	if len(paths) != 2 {
		fmt.Fprintln(stderr, "usage: difftool [flags] OLD NEW")
		fs.PrintDefaults()
		return 2
	}

	oldText, err := readInput(paths[0])
	if err != nil {
		fmt.Fprintf(stderr, "difftool: %v\n", err)
		return 2
	}
	newText, err := readInput(paths[1])
	if err != nil {
		fmt.Fprintf(stderr, "difftool: %v\n", err)
		return 2
	}

	opts := diff.Options{
		FromFile: label(*fromLabel, paths[0]),
		ToFile:   label(*toLabel, paths[1]),
		Context:  *context,
	}

	out, err := diff.UnifiedWithOptions(oldText, newText, opts)
	if err != nil {
		fmt.Fprintf(stderr, "difftool: %v\n", err)
		return 2
	}

	if out == "" {
		return 0
	}
	fmt.Fprint(stdout, out)
	return 1
}

func readInput(path string) (string, error) {
	if path == "-" {
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			return "", fmt.Errorf("reading stdin: %w", err)
		}
		return string(b), nil
	}

	b, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("reading %s: %w", path, err)
	}
	return string(b), nil
}

func label(override, path string) string {
	if override != "" {
		return override
	}
	return path
}

